#!/usr/bin/env bash
# Generated by @@generator@@. Settings: .github/mobile-cicd/config.json
#
# Puts the store release secrets into this repo's GitHub Actions secrets. Run it yourself, in
# your own terminal, from anywhere inside the repo:
#
#   bash .github/mobile-cicd/setup-secrets.sh             every part, one after another
#   bash .github/mobile-cicd/setup-secrets.sh ios         one part: env | ios | android | play | firebase
#   bash .github/mobile-cicd/setup-secrets.sh --check     which secrets exist (names only, no values)
#
# Every value goes from a file or a hidden prompt straight into `gh secret set` through stdin:
# nothing is printed, written into the repo, or put on a command line. Each file is checked
# first (passwords, expiry dates, bundle IDs, and a real call to App Store Connect and Google
# Play), so a mistake shows up here and not 40 minutes into a release build.
set -euo pipefail
umask 077
cd "$(git rev-parse --show-toplevel 2>/dev/null || pwd)"

IOS_BUNDLE_ID=@@sh:ios.bundleId@@
IOS_TEAM_ID=@@sh:ios.teamId@@
ANDROID_PACKAGE=@@sh:android.packageName@@
ENV_SECRET=@@sh:envSecret@@       # empty: the app reads no build-time environment
ENV_FILE=@@sh:envFile@@
ENV_REQUIRED=(@@shlist:envRequired@@)
FIREBASE_IOS=@@sh:firebaseIos@@   # empty: GoogleService-Info.plist is not needed or is committed
FIREBASE_ANDROID=@@sh:firebaseAndroid@@
CHECKER=".github/mobile-cicd/check-store-access.mjs"

REQUIRED=(APP_STORE_CONNECT_API_KEY_ID APP_STORE_CONNECT_ISSUER_ID APP_STORE_CONNECT_API_KEY
  IOS_DISTRIBUTION_CERTIFICATE IOS_DISTRIBUTION_CERTIFICATE_PASSWORD
  ANDROID_KEYSTORE ANDROID_KEYSTORE_PASSWORD ANDROID_KEY_ALIAS
  GOOGLE_PLAY_SERVICE_ACCOUNT_JSON)
OPTIONAL=(IOS_PROVISIONING_PROFILE ANDROID_KEY_PASSWORD)
if [[ -n "$ENV_SECRET" ]]; then REQUIRED+=("$ENV_SECRET"); fi
if [[ -n "$FIREBASE_IOS" ]]; then REQUIRED+=(GOOGLE_SERVICE_INFO_PLIST); fi
if [[ -n "$FIREBASE_ANDROID" ]]; then REQUIRED+=(GOOGLE_SERVICES_JSON); fi

die() { echo "error: $*" >&2; exit 1; }
yes_no() { local a; read -r -p "$1 " a; [[ "$a" == [yY]* ]]; }
TMP_FILES=()
cleanup() { if ((${#TMP_FILES[@]})); then rm -f "${TMP_FILES[@]}"; fi; }
trap cleanup EXIT

command -v gh >/dev/null 2>&1 || die "the GitHub CLI is needed: https://cli.github.com"
gh auth status >/dev/null 2>&1 || die "sign in to GitHub first: gh auth login"
REPO="$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null)" || die "run this inside the app's GitHub repo"

EXISTING=""
refresh() { EXISTING=" $(gh secret list -R "$REPO" 2>/dev/null | awk '{print $1}' | tr '\n' ' ') "; }
has() { [[ "$EXISTING" == *" $1 "* ]]; }
refresh

# ------------------------------------------------------------------ helpers
put() { # put NAME   (the value comes on stdin)
  gh secret set "$1" -R "$REPO" >/dev/null || { echo "  could not set $1" >&2; return 1; }
  EXISTING+="$1 "
  echo "  set $1"
}
put_b64() { base64 < "$2" | tr -d '\n' | put "$1"; }

# Asks before replacing a secret that is already set. Returns 1 to skip.
replace_ok() {
  has "$1" || return 0
  yes_no "  $1 is already set. Replace it? [y/N]" || { echo "  kept $1"; return 1; }
}

ask_hidden() { local v; read -r -s -p "$1: " v; echo >&2; printf '%s' "$v"; }

# Reads a path; accepts a file dragged into the terminal (escaped spaces, quotes, trailing space).
ask_path() { # ask_path PROMPT [DEFAULT]
  local p
  read -r -p "$1${2:+ [$2]}: " p
  p="${p:-${2:-}}"
  p="${p%"${p##*[![:space:]]}"}"
  p="${p//\\ / }"; p="${p#\'}"; p="${p%\'}"; p="${p#\"}"; p="${p%\"}"
  p="${p/#\~/$HOME}"
  printf '%s' "$p"
}
ask_file() {
  local f; f="$(ask_path "$@")"
  [[ -n "$f" && -f "$f" ]] || { echo "  no file at '$f'" >&2; return 1; }
  printf '%s' "$f"
}

find_keytool() {
  local candidates=(
    "${JAVA_HOME:+$JAVA_HOME/bin/keytool}"
    "/Applications/Android Studio.app/Contents/jbr/Contents/Home/bin/keytool"
    "$(command -v keytool 2>/dev/null || true)"
  )
  for k in "${candidates[@]}"; do
    if [[ -n "$k" && -x "$k" ]] && "$k" -help >/dev/null 2>&1; then KEYTOOL="$k"; return 0; fi
  done
  echo "  keytool not found: install a JDK or Android Studio (it ships one)." >&2
  return 1
}

# ------------------------------------------------------------------ --check
check() {
  refresh
  local missing=0
  echo "Secrets in $REPO (names only):"
  for s in "${REQUIRED[@]}"; do
    if has "$s"; then echo "  ok        $s"; else echo "  MISSING   $s"; missing=$((missing + 1)); fi
  done
  for s in "${OPTIONAL[@]}"; do
    if has "$s"; then echo "  ok        $s (optional)"; else echo "  -         $s (optional)"; fi
  done
  if ((missing)); then
    echo "$missing required secret(s) missing. Set them with: bash .github/mobile-cicd/setup-secrets.sh"
    return 1
  fi
  echo "All required secrets are set."
}

# ------------------------------------------------------------------ parts
part_env() {
  if [[ -z "$ENV_SECRET" ]]; then echo "==> Build environment: not needed"; return 0; fi
  echo "==> Build environment: $ENV_FILE -> $ENV_SECRET"
  replace_ok "$ENV_SECRET" || return 0
  local f missing=()
  f="$(ask_file "Production env file" "$ENV_FILE")" || return 1
  # ${a[@]+...}: macOS's bash 3.2 treats an empty array as unset under `set -u`.
  for k in ${ENV_REQUIRED[@]+"${ENV_REQUIRED[@]}"}; do
    grep -qE "^[[:space:]]*(export[[:space:]]+)?$k=." "$f" || missing+=("$k")
  done
  if ((${#missing[@]})); then
    echo "  The code reads these, but $f gives no value for them: ${missing[*]}"
    yes_no "  Upload it anyway? [y/N]" || return 1
  fi
  put "$ENV_SECRET" < "$f"
}

part_ios() {
  echo "==> iOS 1/3: App Store Connect API key"
  echo "    App Store Connect -> Users and Access -> Integrations -> App Store Connect API -> Team Keys,"
  echo "    a key with the App Manager role. The .p8 file can be downloaded only once."
  if replace_ok APP_STORE_CONNECT_API_KEY; then
    local p8 key_id issuer latest
    latest="$(ls -t "$HOME"/Downloads/AuthKey_*.p8 2>/dev/null | head -1 || true)"
    p8="$(ask_file "API key file (AuthKey_XXXXXXXXXX.p8)" "$latest")" || return 1
    grep -q "BEGIN PRIVATE KEY" "$p8" || { echo "  That file is not a .p8 private key."; return 1; }
    key_id="$(basename "$p8" .p8)"; key_id="${key_id#AuthKey_}"
    [[ "$key_id" =~ ^[A-Z0-9]{10}$ ]] || read -r -p "Key ID (10 characters, shown next to the key): " key_id
    [[ "$key_id" =~ ^[A-Z0-9]{10}$ ]] || { echo "  That is not a Key ID."; return 1; }
    read -r -p "Issuer ID (the UUID above the list of keys): " issuer
    [[ "$issuer" =~ ^[0-9a-fA-F-]{36}$ ]] || { echo "  That is not an Issuer ID."; return 1; }
    local status=0
    ASC_KEY_ID="$key_id" ASC_ISSUER_ID="$issuer" ASC_KEY_PATH="$p8" node "$CHECKER" app-store "$IOS_BUNDLE_ID" || status=$?
    if ((status == 1)); then yes_no "  Upload it anyway? [y/N]" || return 1; fi
    printf '%s' "$key_id" | put APP_STORE_CONNECT_API_KEY_ID || return 1
    printf '%s' "$issuer" | put APP_STORE_CONNECT_ISSUER_ID || return 1
    put_b64 APP_STORE_CONNECT_API_KEY "$p8" || return 1
  fi

  echo "==> iOS 2/3: Apple Distribution certificate (.p12)"
  echo "    Keychain Access -> My Certificates -> \"Apple Distribution: ...\" -> right click -> Export, with a password."
  CERT_SHA1=""
  if replace_ok IOS_DISTRIBUTION_CERTIFICATE; then
    local p12 pw="" opened=false info subject
    p12="$(ask_file "Certificate file (.p12)")" || return 1
    for try in 1 2 3; do
      pw="$(ask_hidden "Password of that .p12 (try $try/3)")"
      if P12_PW="$pw" openssl pkcs12 -in "$p12" -passin env:P12_PW -nokeys -clcerts -out /dev/null 2>/dev/null ||
        P12_PW="$pw" openssl pkcs12 -legacy -in "$p12" -passin env:P12_PW -nokeys -clcerts -out /dev/null 2>/dev/null; then
        opened=true; break
      fi
      echo "  that password does not open the file"
    done
    $opened || { echo "  Export the certificate again with a password you know, then run: bash $0 ios"; return 1; }
    info="$( { P12_PW="$pw" openssl pkcs12 -in "$p12" -passin env:P12_PW -nokeys -clcerts 2>/dev/null ||
      P12_PW="$pw" openssl pkcs12 -legacy -in "$p12" -passin env:P12_PW -nokeys -clcerts 2>/dev/null; } |
      openssl x509 -noout -subject -enddate -fingerprint -sha1 2>/dev/null || true)"
    subject="$(sed -n 's/^subject= *//p' <<<"$info")"
    CERT_SHA1="$(sed -n 's/^[Ss][Hh][Aa]1 [Ff]ingerprint=//p' <<<"$info")"
    if [[ -n "$info" ]]; then
      echo "  $subject"
      echo "  expires $(sed -n 's/^notAfter=//p' <<<"$info")"
      [[ "$subject" == *Distribution* ]] || { echo "  This is not a distribution certificate (App Store builds need \"Apple Distribution\")."; return 1; }
      if ! { P12_PW="$pw" openssl pkcs12 -in "$p12" -passin env:P12_PW -nokeys -clcerts 2>/dev/null ||
        P12_PW="$pw" openssl pkcs12 -legacy -in "$p12" -passin env:P12_PW -nokeys -clcerts 2>/dev/null; } | openssl x509 -noout -checkend 0 >/dev/null 2>&1; then
        echo "  This certificate has expired. Create a new one in Apple Developer -> Certificates."; return 1
      fi
    fi
    put_b64 IOS_DISTRIBUTION_CERTIFICATE "$p12" || return 1
    printf '%s' "$pw" | put IOS_DISTRIBUTION_CERTIFICATE_PASSWORD || return 1
    pw=""
  fi

  echo "==> iOS 3/3: App Store provisioning profile (optional)"
  echo "    Skip it and fastlane fetches, or creates, one with the API key on each build."
  if replace_ok IOS_PROVISIONING_PROFILE; then
    local prof
    prof="$(ask_path "App Store .mobileprovision file (Enter to skip)")"
    if [[ -n "$prof" ]]; then
      [[ -f "$prof" ]] || { echo "  no file at '$prof'"; return 1; }
      check_profile "$prof" || return 1
      put_b64 IOS_PROVISIONING_PROFILE "$prof" || return 1
    fi
  fi
}

check_profile() {
  command -v security >/dev/null 2>&1 || { echo "  (profile not checked: needs macOS)"; return 0; }
  local plist appid expires now i=0 cert fp match=false
  plist="$(mktemp)"
  TMP_FILES+=("$plist")
  security cms -D -i "$1" >"$plist" 2>/dev/null || { echo "  That is not a provisioning profile."; return 1; }
  appid="$(plutil -extract Entitlements.application-identifier raw -o - "$plist" 2>/dev/null || true)"
  if [[ "$appid" != "$IOS_TEAM_ID.$IOS_BUNDLE_ID" ]]; then
    echo "  The profile is for $appid, not $IOS_TEAM_ID.$IOS_BUNDLE_ID."; return 1
  fi
  if plutil -extract ProvisionedDevices raw -o - "$plist" >/dev/null 2>&1; then
    echo "  This profile lists devices (development or ad hoc). Create an App Store profile."; return 1
  fi
  expires="$(plutil -extract ExpirationDate raw -o - "$plist" 2>/dev/null || true)"
  now="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  if [[ -n "$expires" && "$expires" < "$now" ]]; then echo "  This profile expired on $expires."; return 1; fi
  if [[ -n "$CERT_SHA1" ]]; then
    while cert="$(plutil -extract "DeveloperCertificates.$i" raw -o - "$plist" 2>/dev/null)"; do
      fp="$(printf '%s' "$cert" | base64 --decode 2>/dev/null | openssl x509 -inform DER -noout -fingerprint -sha1 2>/dev/null | sed 's/^.*=//')"
      [[ "${fp//:/}" == "${CERT_SHA1//:/}" ]] && match=true
      i=$((i + 1))
    done
    $match || { echo "  The profile does not include the certificate you just set. Regenerate the profile with it."; return 1; }
  fi
  echo "  profile OK: App Store, $appid, expires $expires"
}

part_android() {
  echo "==> Android: upload key (it signs every bundle you send to Google Play)"
  replace_ok ANDROID_KEYSTORE || return 0
  find_keytool || return 1
  local ks alias pw kpw="" sha
  ks="$(ask_path "Keystore file (.jks or .keystore). Enter to create a new upload key")"
  if [[ -z "$ks" ]]; then
    local dir="$HOME/.mobile-cicd/$ANDROID_PACKAGE"
    ks="$dir/upload.keystore"; alias="upload"
    [[ ! -e "$ks" ]] || { echo "  $ks already exists. Give its path instead of creating a new one."; return 1; }
    mkdir -p "$dir"; chmod 700 "$dir"
    pw="$(openssl rand -base64 48 | tr -dc 'A-Za-z0-9' | cut -c1-32)"
    KS_PW="$pw" "$KEYTOOL" -genkeypair -storetype PKCS12 -keystore "$ks" -alias "$alias" \
      -keyalg RSA -keysize 2048 -validity 10000 -dname "CN=$ANDROID_PACKAGE" \
      -storepass:env KS_PW -keypass:env KS_PW >/dev/null 2>&1 || { echo "  keytool could not create the key."; return 1; }
    chmod 600 "$ks"
    if command -v security >/dev/null 2>&1; then
      # `security` takes the password as an argument (seen by local processes for a moment).
      security add-generic-password -U -s "$ANDROID_PACKAGE upload key" -a "$alias" -w "$pw"
      echo "  Created $ks. Its password is in your Keychain as \"$ANDROID_PACKAGE upload key\"."
    else
      printf '%s\n' "$pw" >"$dir/password.txt"
      echo "  Created $ks. Its password is in $dir/password.txt (readable only by you):"
      echo "  move it into your password manager, then delete that file."
    fi
    echo "  BACK UP the keystore file and its password now (password manager). Without them you cannot"
    echo "  ship updates until Google resets the upload key, which takes days."
  else
    [[ -f "$ks" ]] || { echo "  no file at '$ks'"; return 1; }
    pw="$(ask_hidden "Keystore password")"
    KS_PW="$pw" "$KEYTOOL" -list -keystore "$ks" -storepass:env KS_PW >/dev/null 2>&1 || { echo "  That password does not open the keystore."; return 1; }
    local aliases
    aliases="$(KS_PW="$pw" "$KEYTOOL" -list -keystore "$ks" -storepass:env KS_PW 2>/dev/null | awk -F', ' '/PrivateKeyEntry/ {print $1}')"
    if [[ "$(wc -l <<<"$aliases" | tr -d ' ')" == 1 && -n "$aliases" ]]; then alias="$aliases"; echo "  key alias: $alias"
    else echo "  Keys in it: $(tr '\n' ' ' <<<"$aliases")"; read -r -p "Key alias: " alias; fi
    KS_PW="$pw" "$KEYTOOL" -list -keystore "$ks" -storepass:env KS_PW -alias "$alias" >/dev/null 2>&1 || { echo "  No key named '$alias' in it."; return 1; }
    kpw="$(ask_hidden "Key password (Enter if it is the same as the keystore password)")"
    if [[ -n "$kpw" && "$kpw" != "$pw" ]]; then
      KS_PW="$pw" K_PW="$kpw" "$KEYTOOL" -certreq -keystore "$ks" -storepass:env KS_PW -alias "$alias" -keypass:env K_PW >/dev/null 2>&1 ||
        { echo "  That key password is wrong."; return 1; }
    else
      kpw=""
    fi
  fi
  sha="$(KS_PW="$pw" "$KEYTOOL" -list -v -keystore "$ks" -storepass:env KS_PW -alias "$alias" 2>/dev/null | awk '$1 == "SHA256:" {print $2; exit}')"
  echo "  Upload key SHA-256: $sha"
  echo "  If the app is already on Google Play, this must match Play Console -> Test and release -> App integrity -> Upload key certificate."
  put_b64 ANDROID_KEYSTORE "$ks" || return 1
  printf '%s' "$pw" | put ANDROID_KEYSTORE_PASSWORD || return 1
  printf '%s' "$alias" | put ANDROID_KEY_ALIAS || return 1
  if [[ -n "$kpw" ]]; then printf '%s' "$kpw" | put ANDROID_KEY_PASSWORD || return 1; fi
  pw=""; kpw=""
}

part_play() {
  echo "==> Google Play: service account key (JSON)"
  echo "    Google Cloud console -> IAM -> Service accounts -> create one -> Keys -> Add key -> JSON."
  echo "    Then Play Console -> Users and permissions -> invite its email with release rights for this app."
  replace_ok GOOGLE_PLAY_SERVICE_ACCOUNT_JSON || return 0
  local json status=0
  json="$(ask_file "Service account key (.json)")" || return 1
  PLAY_JSON_PATH="$json" node "$CHECKER" play "$ANDROID_PACKAGE" || status=$?
  if ((status == 1)); then yes_no "  Upload it anyway? [y/N]" || return 1; fi
  put GOOGLE_PLAY_SERVICE_ACCOUNT_JSON < "$json"
}

part_firebase() {
  if [[ -z "$FIREBASE_IOS$FIREBASE_ANDROID" ]]; then echo "==> Firebase files: not needed"; return 0; fi
  echo "==> Firebase config files (Firebase console -> Project settings -> Your apps)"
  local f
  if [[ -n "$FIREBASE_IOS" ]] && replace_ok GOOGLE_SERVICE_INFO_PLIST; then
    f="$(ask_file "GoogleService-Info.plist" "$FIREBASE_IOS")" || return 1
    grep -q "<string>$IOS_BUNDLE_ID</string>" "$f" || { echo "  That plist is not for $IOS_BUNDLE_ID."; return 1; }
    put_b64 GOOGLE_SERVICE_INFO_PLIST "$f" || return 1
  fi
  if [[ -n "$FIREBASE_ANDROID" ]] && replace_ok GOOGLE_SERVICES_JSON; then
    f="$(ask_file "google-services.json" "$FIREBASE_ANDROID")" || return 1
    grep -q "\"package_name\": *\"$ANDROID_PACKAGE\"" "$f" || { echo "  That file has no client for $ANDROID_PACKAGE."; return 1; }
    put_b64 GOOGLE_SERVICES_JSON "$f" || return 1
  fi
}

# ------------------------------------------------------------------ main
case "${1:-all}" in
  --check) check; exit $? ;;
  -h | --help) sed -n '2,15p' "$0"; exit 0 ;;
  all) PARTS=(env ios android play firebase) ;;
  env | ios | android | play | firebase) PARTS=("$1") ;;
  *) die "unknown part '$1' (env | ios | android | play | firebase | --check)" ;;
esac

command -v node >/dev/null 2>&1 || die "Node.js is needed for the store checks"
echo "Secrets go to: $REPO"
yes_no "Continue? [y/N]" || exit 0
echo

FAILED=()
for part in "${PARTS[@]}"; do
  "part_$part" || FAILED+=("$part")
  echo
done
check || true
if ((${#FAILED[@]})); then
  echo
  echo "Not finished: ${FAILED[*]}. Fix what is shown above, then run only that part again:"
  echo "  bash .github/mobile-cicd/setup-secrets.sh ${FAILED[0]}"
  exit 1
fi
